// <chart-area-chart> — area chart with recharts-parity SVG markup.
// d3 (via math.ts) is geometry only; every visible class and attribute
// matches what recharts renders inside shadcn's ChartContainer: areas are
// `recharts-curve recharts-area-area` + `recharts-curve recharts-area-curve`,
// layers are `recharts-layer`, the svg is `recharts-surface`, the tooltip
// cursor is a vertical `recharts-curve recharts-tooltip-cursor` line with
// literal stroke="#ccc" (the container CSS turns it into stroke-border).
// Series colors are always `var(--color-<dataKey>)` — never resolved in JS —
// so a shadcn theme's --chart-1..5 variables restyle everything.
import {
  areaPaths,
  cartesianCtx,
  stackSeries,
  thinTicksByGap,
  type CartesianCtx,
  type CurveType,
  type Margin,
  type Row,
} from "./math.ts";
import { configFor, seriesColor, type ChartConfig } from "./config.ts";
import { cn } from "../../../lib/utils.ts";
import ChartGrid from "./grid.marko";
import ChartXAxis from "./x-axis.marko";
import ChartYAxis from "./y-axis.marko";
import ChartTooltip from "./tooltip.marko";
import ChartLegend from "./legend.marko";

export interface AreaSeriesAttrs {
  dataKey: string;
  /** Curve type (recharts `type`). Default "natural", like the shadcn demos. */
  type?: CurveType;
  /** Series sharing a stackId stack on top of each other (declaration order = bottom to top). */
  stackId?: string;
  /** Fill with a per-series <linearGradient> fading the series color 0.8 → 0.1. */
  gradient?: boolean;
  fillOpacity?: number;
}

export interface Input {
  /** Same object passed to <Chart> — Marko has no context, so it's passed twice. */
  config: ChartConfig;
  data: Row[];
  /** Category field for the x axis, e.g. "month". */
  xKey: string;
  /** viewBox size — the container's CSS aspect scales the drawing. */
  width?: number;
  height?: number;
  margin?: Partial<Margin>;
  tooltip?: boolean;
  /** Vertical cursor line on hover (recharts default). Shadcn area demos pass false. */
  cursor?: boolean;
  indicator?: "line" | "dot" | "dashed";
  hideLabel?: boolean;
  /** Horizontal grid lines (recharts <CartesianGrid vertical={false}/>). */
  grid?: boolean;
  yAxis?: boolean;
  /** Approximate number of y-axis ticks (recharts YAxis tickCount). Default 5. */
  yAxisTickCount?: number;
  legend?: boolean | "top" | "bottom";
  /** Applied to axis tick labels only (like recharts' XAxis tickFormatter). */
  xTickFormatter?: (value: string) => string;
  /** Minimum pixel gap between kept x-axis ticks (recharts XAxis minTickGap) — thins dense date-series ticks. */
  xTickMinGap?: number;
  /** Applied to the tooltip's label row only (recharts ChartTooltipContent labelFormatter). */
  tooltipLabelFormatter?: (value: string) => string;
  /** "expand" ⇒ 100% stacked (recharts stackOffset="expand"). Requires stacked series. */
  stackOffset?: "expand";
  series?: Marko.AttrTag<AreaSeriesAttrs>;
  class?: string;
}

export interface AreaGeom {
  key: string;
  areaD: string;
  lineD: string;
  gradient: boolean;
  fillOpacity: number;
}

static function numberAt(row: Row, key: string): number {
  const value = row[key];
  return typeof value === "number" ? value : Number(value ?? 0);
}

// Point-scale x positions, like recharts uses for area/line charts: the
// first point sits at the plot's left edge, the last at its right edge
// (the default left/right margin of 12 gives the curve breathing room).
static function pointPositions(ctx: CartesianCtx, count: number): number[] {
  if (count <= 1) return [ctx.plot.x + ctx.plot.width / 2];
  const step = ctx.plot.width / (count - 1);
  return Array.from({ length: count }, (item, index) => ctx.plot.x + index * step);
}

static function buildAreas(
  ctx: CartesianCtx,
  seriesList: AreaSeriesAttrs[],
  positions: number[],
  stackOffset?: "expand",
): AreaGeom[] {
  const stackedKeys = seriesList
    .filter((series) => series.stackId != null)
    .map((series) => series.dataKey);
  const stacks = stackedKeys.length
    ? stackSeries(ctx.data, stackedKeys, { offset: stackOffset })
    : [];
  const baselineY = ctx.y(Math.max(0, ctx.y.domain()[0] ?? 0));
  return seriesList.map((series) => {
    const curve = series.type ?? "natural";
    const stackIndex = stackedKeys.indexOf(series.dataKey);
    const layer = stackIndex >= 0 ? stacks[stackIndex] : undefined;
    const paths = areaPaths(
      ctx.data,
      (row, index) => positions[index] ?? 0,
      // d3 stack() emits one segment per data row, so layer[index] is always
      // present when `layer` exists; the ?? [0, 0] keeps a malformed
      // data/keys pairing from throwing mid-path.
      (row, index) => (layer ? ctx.y((layer[index] ?? [0, 0])[0]) : baselineY),
      (row, index) =>
        layer
          ? ctx.y((layer[index] ?? [0, 0])[1])
          : ctx.y(numberAt(row, series.dataKey)),
      curve,
    );
    return {
      key: series.dataKey,
      areaD: paths.area,
      lineD: paths.line,
      gradient: series.gradient === true,
      fillOpacity: series.fillOpacity ?? 0.4,
    };
  });
}

static function seriesLabel(config: ChartConfig, key: string): string {
  return configFor(config, key)?.label ?? key;
}

static function tooltipRowsFor(
  config: ChartConfig,
  seriesList: AreaSeriesAttrs[],
  row: Row,
): { key: string; label: string; value: number; color: string }[] {
  return seriesList.map((series) => ({
    key: series.dataKey,
    label: seriesLabel(config, series.dataKey),
    value: numberAt(row, series.dataKey),
    color: seriesColor(series.dataKey),
  }));
}

static function legendItemsFor(
  config: ChartConfig,
  seriesList: AreaSeriesAttrs[],
): { key: string; label: string; color: string; icon?: Marko.Renderable }[] {
  return seriesList.map((series) => ({
    key: series.dataKey,
    label: seriesLabel(config, series.dataKey),
    color: seriesColor(series.dataKey),
    icon: configFor(config, series.dataKey)?.icon,
  }));
}

static function tooltipLeft(center: number, width: number): string {
  const pct = (center / width) * 100;
  return `${Math.max(6, Math.min(78, pct))}%`;
}

// Pointer → nearest point index, on plain numbers only: the d3 scales in
// `ctx` are not serializable, so the client hover math runs on a precomputed
// plain geometry object (point scale — nearest point wins, like recharts).
static function pointerIndex(
  offsetX: number,
  clientWidth: number,
  geom: { width: number; plotX: number; plotWidth: number; count: number },
): number {
  if (clientWidth <= 0 || geom.count === 0) return -1;
  const scaledX = offsetX * (geom.width / clientWidth);
  if (scaledX < geom.plotX || scaledX > geom.plotX + geom.plotWidth) return -1;
  if (geom.count === 1) return 0;
  const step = geom.plotWidth / (geom.count - 1);
  const index = Math.round((scaledX - geom.plotX) / step);
  return Math.max(0, Math.min(geom.count - 1, index));
}

<const/{
  config,
  data,
  xKey,
  width = 628,
  height = 353,
  tooltip: showTooltip = true,
  cursor = true,
  indicator = "dot",
  hideLabel,
  grid: showGrid = true,
  yAxis: showYAxis = false,
  yAxisTickCount,
  legend,
  xTickFormatter,
  tooltipLabelFormatter,
  stackOffset,
  class: className,
}=input/>
<id/uid/>
<const/seriesList=[...(input.series ?? [])]/>
<const/seriesKeys=seriesList.map((series) => series.dataKey)/>
<const/stacked=seriesList.some((series) => series.stackId != null)/>
<const/ctx=cartesianCtx({
  data,
  xKey,
  seriesKeys,
  width,
  height,
  margin: { left: 12, right: 12, ...input.margin },
  xAxisHeight: 30,
  stacked,
  stackOffset,
  paddingInner: 0,
  paddingOuter: 0,
})/>
// Everything the client (hover state) touches must be plain data — the d3
// scales inside ctx are not serializable, so precompute per-index geometry.
<const/centers=pointPositions(ctx, data.length)/>
<const/areas=buildAreas(ctx, seriesList, centers, stackOffset)/>
<const/allTicks=data.map((row, index) => ({
  value: (xTickFormatter ? xTickFormatter(String(row[xKey])) : String(row[xKey])),
  x: centers[index] ?? 0,
}))/>
<const/ticks=(input.xTickMinGap ? thinTicksByGap(allTicks, input.xTickMinGap) : allTicks)/>
<const/gradients=areas.filter((geom) => geom.gradient)/>
<const/plotTop=ctx.plot.y/>
<const/plotBottom=(ctx.plot.y + ctx.plot.height)/>
<const/pointerGeom={
  width,
  plotX: ctx.plot.x,
  plotWidth: ctx.plot.width,
  count: data.length,
}/>
<const/tooltipItems=data.map((row) => ({
  label: (tooltipLabelFormatter ? tooltipLabelFormatter(String(row[xKey])) : String(row[xKey])),
  rows: tooltipRowsFor(config, seriesList, row),
}))/>
<let/activeIndex=(-1)/>
<const/activeItem=(showTooltip && activeIndex >= 0 ? tooltipItems[activeIndex] : undefined)/>

<div
  class=cn("recharts-wrapper", className)
  style={ position: "relative", width: "100%", height: "100%" }
  onPointerMove(event, el) {
    const bounds = el.getBoundingClientRect();
    activeIndex = pointerIndex(event.clientX - bounds.left, bounds.width, pointerGeom);
  }
  onPointerLeave() { activeIndex = -1; }
>
  <if=(legend === "top")>
    <ChartLegend items=legendItemsFor(config, seriesList) verticalAlign="top"/>
  </if>
  <svg
    class="recharts-surface"
    width="100%"
    height="100%"
    viewBox=`0 0 ${width} ${height}`
  >
    <if=gradients.length>
      <defs>
        <for|geom| of=gradients>
          <linearGradient
            id=`fill-${uid}-${geom.key}`
            x1="0"
            y1="0"
            x2="0"
            y2="1"
          >
            <stop
              offset="5%"
              stop-color=seriesColor(geom.key)
              stop-opacity="0.8"
            />
            <stop
              offset="95%"
              stop-color=seriesColor(geom.key)
              stop-opacity="0.1"
            />
          </linearGradient>
        </for>
      </defs>
    </if>
    <if=showGrid>
      <ChartGrid ctx=ctx/>
    </if>
    <ChartXAxis ctx=ctx ticks=ticks/>
    <if=showYAxis>
      <ChartYAxis ctx=ctx tickCount=yAxisTickCount/>
    </if>
    <if=(showTooltip && cursor !== false && activeIndex >= 0)>
      <g class="recharts-layer">
        <path
          class="recharts-curve recharts-tooltip-cursor"
          stroke="#ccc"
          fill="none"
          stroke-width="1"
          d=`M ${centers[activeIndex]},${plotTop} L ${centers[activeIndex]},${plotBottom}`
        />
      </g>
    </if>
    <for|geom| of=areas>
      <g class="recharts-layer recharts-area">
        <path
          class="recharts-curve recharts-area-area"
          fill=(geom.gradient ? `url(#fill-${uid}-${geom.key})` : seriesColor(geom.key))
          fill-opacity=geom.fillOpacity
          stroke="none"
          d=geom.areaD
        />
        <path
          class="recharts-curve recharts-area-curve"
          stroke=seriesColor(geom.key)
          fill="none"
          stroke-width="2"
          d=geom.lineD
        />
      </g>
    </for>
  </svg>
  <if=(legend === true || legend === "bottom")>
    <ChartLegend items=legendItemsFor(config, seriesList) verticalAlign="bottom"/>
  </if>
  <if=activeItem>
    <div
      style={
        position: "absolute",
        left: tooltipLeft(centers[activeIndex] ?? 0, width),
        top: "12px",
        "pointer-events": "none",
      }
    >
      <ChartTooltip
        rows=activeItem.rows
        label=activeItem.label
        indicator=indicator
        hideLabel=hideLabel
      />
    </div>
  </if>
</div>

// BarChart — d3-geometry port of recharts' <BarChart> as used by shadcn.
// SSR renders the full chart; the ONLY client JS is the hover state for the
// tooltip/cursor. SVG markup mirrors recharts (recharts-* classes, literal
// default attributes) so the shadcn ChartContainer selectors restyle it
// identically. Series colors are always `var(--color-<dataKey>)` — resolved
// by the container's scoped <style>, never in JS.
//
// `layout="horizontal"` mirrors recharts' own (confusing) naming: passing
// this renders HORIZONTAL bars (category axis on Y, value axis on X) — it
// is recharts' <BarChart layout="vertical"> equivalent. It runs through a
// wholly separate render branch built on math.ts' horizontalCtx family
// rather than reusing CartesianCtx, since the two contexts assign x/y to
// opposite roles (band-on-x vs band-on-y).
import {
  bandCenter,
  bandCursorPath,
  cartesianCtx,
  roundedRectPath,
  stackSeries,
  xTicks,
  thinTicksByGap,
  horizontalCtx,
  hBandTicks,
  hBandCenter,
  hBandCursorPath,
  hBandIndexFromPointer,
  type CartesianCtx,
  type CornerRadius,
  type HorizontalCtx,
  type Margin,
  type Row,
  type XTick,
} from "./math.ts";
import { seriesColor, type ChartConfig } from "./config.ts";
import { cn } from "../../../lib/utils.ts";
import ChartGrid from "./grid.marko";
import ChartXAxis from "./x-axis.marko";
import ChartYAxis from "./y-axis.marko";
import ChartTooltip, { type TooltipRow } from "./tooltip.marko";
import ChartLegend, { type LegendItem } from "./legend.marko";

export interface BarSeries {
  dataKey: string;
  /** recharts Bar radius: number rounds all 4 corners, [tl,tr,br,bl] tuple per corner. */
  radius?: CornerRadius;
}

/** Per-row color override: row.fill (like pie.marko's sliceColor) wins over the series/config color. */
static function barColor(row: Row, dataKey: string): string {
  const fill = row["fill"];
  if (typeof fill === "string" && fill !== "") return fill;
  return seriesColor(dataKey);
}

export interface LabelSpec {
  /** Which field to render — defaults to the bar's own dataKey (value labels). */
  dataKey?: string;
  position?: "top" | "right" | "insideLeft";
  /** CSS color (e.g. "var(--foreground)" or "var(--color-label)"). Default currentColor via fill-foreground parity class. */
  color?: string;
  formatter?: (value: string) => string;
}

export interface PointerGeometry {
  width: number;
  plotX: number;
  plotRight: number;
  start: number;
  step: number;
  count: number;
}

export interface HPointerGeometry {
  height: number;
  plotY: number;
  plotBottom: number;
  start: number;
  step: number;
  count: number;
}

export interface Input {
  /** Same object passed to <Chart> — Marko has no context, so it is passed twice. */
  config: ChartConfig;
  data: Row[];
  xKey: string;
  series?: Marko.AttrTag<BarSeries>;
  width?: number;
  height?: number;
  margin?: Partial<Margin>;
  stacked?: boolean;
  /** Horizontal grid lines (recharts <CartesianGrid vertical={false}/>). Default true. */
  grid?: boolean;
  /** Render the y axis (default false — shadcn demos hide it). */
  yAxis?: boolean;
  legend?: boolean | "top" | "bottom";
  /** Default true. `false` ⇒ no tooltip panel and no cursor. */
  tooltip?: boolean;
  /** Tooltip cursor rect behind the hovered band (recharts default). */
  cursor?: boolean;
  indicator?: "line" | "dot" | "dashed";
  hideLabel?: boolean;
  hideIndicator?: boolean;
  tickMargin?: number;
  xTickFormatter?: (value: string) => string;
  /** Minimum pixel gap between kept x-axis ticks (recharts XAxis minTickGap) — thins dense date-series ticks. */
  xTickMinGap?: number;
  /** Applied to the tooltip's label row only (recharts ChartTooltipContent labelFormatter). */
  tooltipLabelFormatter?: (value: string) => string;
  class?: string;
  /** recharts' own (confusing) naming: "horizontal" renders HORIZONTAL bars. */
  layout?: "horizontal";
  /** category-axis tick formatter (Y axis in horizontal layout, X axis otherwise). */
  categoryTickFormatter?: (value: string) => string;
  /** Bar (or, in horizontal layout, the single-series bar) LabelList-equivalents. */
  labels?: LabelSpec[];
  /** Highlights one bar (fill-opacity 0.8, dashed stroke in its own row.fill color) — mirrors chart-bar-active. */
  activeIndex?: number;
}

// recharts default gap between series bars within a band (barGap: 4).
static const BAR_GAP = 4;

static function computeBars(
  ctx: CartesianCtx,
  seriesList: BarSeries[],
  stacked: boolean,
): { dataKey: string; paths: string[] }[] {
  const bandwidth = ctx.xBand.bandwidth();
  const baseline = ctx.y(0);
  if (stacked) {
    const stacks = stackSeries(
      ctx.data,
      seriesList.map((series) => series.dataKey),
    );
    return seriesList.map((series, seriesIndex) => {
      const layer = stacks[seriesIndex];
      const paths = ctx.data.map((row, rowIndex) => {
        const x = ctx.xBand(String(row[ctx.xKey])) ?? 0;
        // d3 stack() emits one layer per key and one segment per row, so these
        // are always present; fall back to an empty [0, 0] band so a malformed
        // data/keys pairing renders nothing rather than crashing.
        const segment = layer?.[rowIndex] ?? [0, 0];
        const top = ctx.y(segment[1]);
        const segmentHeight = ctx.y(segment[0]) - ctx.y(segment[1]);
        return roundedRectPath(x, top, bandwidth, segmentHeight, series.radius ?? 0);
      });
      return { dataKey: series.dataKey, paths };
    });
  }
  const count = seriesList.length;
  const gap = count > 1 ? BAR_GAP : 0;
  const barWidth = (bandwidth - gap * (count - 1)) / count;
  return seriesList.map((series, seriesIndex) => {
    const paths = ctx.data.map((row) => {
      const x =
        (ctx.xBand(String(row[ctx.xKey])) ?? 0) + seriesIndex * (barWidth + gap);
      const value = Number(row[series.dataKey] ?? 0);
      const top = Math.min(ctx.y(value), baseline);
      const barHeight = Math.abs(baseline - ctx.y(value));
      return roundedRectPath(x, top, barWidth, barHeight, series.radius ?? 0);
    });
    return { dataKey: series.dataKey, paths };
  });
}

/** Single-series bar geometry (per-bar x/top/height/width), for the row-colored / labeled / active-highlight paths. */
static function computeSingleBars(
  ctx: CartesianCtx,
  dataKey: string,
  radius: CornerRadius | undefined,
): { row: Row; x: number; top: number; width: number; height: number; path: string }[] {
  const bandwidth = ctx.xBand.bandwidth();
  const baseline = ctx.y(0);
  return ctx.data.map((row) => {
    const x = ctx.xBand(String(row[ctx.xKey])) ?? 0;
    const value = Number(row[dataKey] ?? 0);
    const top = Math.min(ctx.y(value), baseline);
    const height = Math.abs(baseline - ctx.y(value));
    return { row, x, top, width: bandwidth, height, path: roundedRectPath(x, top, bandwidth, height, radius ?? 0) };
  });
}

static function formatTicks(
  ctx: CartesianCtx,
  formatter?: (value: string) => string,
): XTick[] {
  const ticks = xTicks(ctx);
  if (!formatter) return ticks;
  return ticks.map((tick) => ({ value: formatter(tick.value), x: tick.x }));
}

static function tooltipRowsByIndex(
  ctx: CartesianCtx,
  seriesList: BarSeries[],
  config: ChartConfig,
): TooltipRow[][] {
  return ctx.data.map((row) =>
    seriesList.map((series) => ({
      key: series.dataKey,
      label: String(config[series.dataKey]?.label ?? series.dataKey),
      value: Number(row[series.dataKey] ?? 0),
      color: barColor(row, series.dataKey),
    })),
  );
}

static function tooltipLefts(ctx: CartesianCtx): string[] {
  return ctx.data.map((row, index) => {
    const center = bandCenter(ctx, index);
    const percent = Math.max(0, Math.min(78, (center / ctx.width) * 100));
    return `${percent.toFixed(2)}%`;
  });
}

static function legendItemsFor(
  seriesList: BarSeries[],
  config: ChartConfig,
): LegendItem[] {
  return seriesList.map((series) => ({
    key: series.dataKey,
    label: String(config[series.dataKey]?.label ?? series.dataKey),
    color: seriesColor(series.dataKey),
  }));
}

static function pointerGeometry(ctx: CartesianCtx): PointerGeometry {
  const domain = ctx.xBand.domain();
  const step = ctx.xBand.step();
  const first = ctx.xBand(domain[0] ?? "") ?? 0;
  return {
    width: ctx.width,
    plotX: ctx.plot.x,
    plotRight: ctx.plot.x + ctx.plot.width,
    start: first - ctx.xBand.paddingInner() * step * 0.5,
    step,
    count: domain.length,
  };
}

// Serializable-geometry twin of math.ts' bandIndexFromPointer: the hover
// handler runs on the client, where the d3 scales in ctx can't be shipped.
static function indexFromPointer(
  offsetX: number,
  clientWidth: number,
  geometry: PointerGeometry,
): number {
  if (clientWidth <= 0 || geometry.count === 0) return -1;
  const scaledX = offsetX * (geometry.width / clientWidth);
  if (scaledX < geometry.plotX || scaledX > geometry.plotRight) return -1;
  const index = Math.floor((scaledX - geometry.start) / geometry.step);
  return Math.max(0, Math.min(geometry.count - 1, index));
}

static function hPointerGeometry(ctx: HorizontalCtx): HPointerGeometry {
  const domain = ctx.yBand.domain();
  const step = ctx.yBand.step();
  const first = ctx.yBand(domain[0] ?? "") ?? 0;
  return {
    height: ctx.height,
    plotY: ctx.plot.y,
    plotBottom: ctx.plot.y + ctx.plot.height,
    start: first - ctx.yBand.paddingInner() * step * 0.5,
    step,
    count: domain.length,
  };
}

static function hIndexFromPointer(
  offsetY: number,
  clientHeight: number,
  geometry: HPointerGeometry,
): number {
  if (clientHeight <= 0 || geometry.count === 0) return -1;
  const scaledY = offsetY * (geometry.height / clientHeight);
  if (scaledY < geometry.plotY || scaledY > geometry.plotBottom) return -1;
  const index = Math.floor((scaledY - geometry.start) / geometry.step);
  return Math.max(0, Math.min(geometry.count - 1, index));
}

static function hComputeBars(
  ctx: HorizontalCtx,
  dataKey: string,
  radius: CornerRadius | undefined,
): { row: Row; y: number; left: number; width: number; height: number; path: string }[] {
  const bandwidth = ctx.yBand.bandwidth();
  const baseline = ctx.x(0);
  return ctx.data.map((row) => {
    const y = ctx.yBand(String(row[ctx.yKey])) ?? 0;
    const value = Number(row[dataKey] ?? 0);
    const left = Math.min(ctx.x(value), baseline);
    const width = Math.abs(baseline - ctx.x(value));
    return { row, y, left, width, height: bandwidth, path: roundedRectPath(left, y, width, bandwidth, radius ?? 0) };
  });
}

static function hFormatTicks(
  ctx: HorizontalCtx,
  formatter?: (value: string) => string,
): { value: string; y: number }[] {
  const ticks = hBandTicks(ctx);
  if (!formatter) return ticks;
  return ticks.map((tick) => ({ value: formatter(tick.value), y: tick.y }));
}

<const/{
  config,
  data,
  xKey,
  width = 628,
  height = 353,
  stacked = false,
  grid: showGrid = true,
  yAxis: showYAxis = false,
  tooltip: tooltipEnabled = true,
  cursor: cursorEnabled = true,
  indicator,
  hideLabel,
  hideIndicator,
  tickMargin = 8,
  class: className,
  layout,
  labels: labelSpecs,
  activeIndex: staticActiveIndex,
}=input/>
<const/horizontal=(layout === "horizontal")/>

<const/seriesList=[...(input.series ?? [])]/>
<const/seriesKeys=seriesList.map((series) => series.dataKey)/>
<const/singleKey=(seriesKeys[0] ?? "")/>
<const/singleRadius=(seriesList[0]?.radius)/>

// Both layout branches' full const chains are computed UNCONDITIONALLY,
// every render, rather than nested inside `<if=horizontal>`/`<else>`.
//
// LANDMINE: a `<const>` chain nested inside an `<if>/<else>` branch does
// not reliably survive Marko 6's fine-grained reactive updates when only a
// DESCENDANT attr-tag input changes (not the branch's own condition). Bar
// charts nested their vertical-layout `ctx` (and everything derived from
// it: cursorPaths, geometry, etc.) inside `<else>` here during the
// horizontal-layout extension; the moment `chart-bar-interactive`'s
// `<@series dataKey=activeChart/>` toggled `activeChart` (a demo-file
// `<let>`, `horizontal` itself never changes), the reactive update that
// recomputed `cursorPaths` ran with `ctx` unresolved, crashing on
// `ctx.xBand.domain()` inside `bandCursorPath`. line.marko/area.marko
// never nest their core const chain in an `<if>` and never hit this.
// Fix: compute both `ctx` and `hCtx` (and their downstream consts) at the
// template's top level, unconditionally; branch ONLY in the markup below.
<const/hCtx=horizontalCtx({
  data,
  yKey: xKey,
  seriesKeys,
  width,
  height,
  margin: { top: 5, right: 5, bottom: 5, left: 5, ...input.margin },
  yAxisWidth: (showYAxis ? 60 : 0),
  stacked,
})/>
<const/hBars=hComputeBars(hCtx, singleKey, singleRadius)/>
<const/hTicks=hFormatTicks(hCtx, input.categoryTickFormatter)/>
<const/hRowsByIndex=data.map((row) => [{
  key: singleKey,
  label: String(config[singleKey]?.label ?? singleKey),
  value: Number(row[singleKey] ?? 0),
  color: barColor(row, singleKey),
