// LineChart — recharts-parity line chart. d3 (via math.ts) is the geometry
// engine only; this template emits the same SVG structure, classes, and
// literal default attributes recharts renders, so the shadcn container's
// selectors (stroke="#fff" dots -> stroke-transparent, the tooltip cursor
// -> stroke-border, tick text -> fill-muted-foreground) restyle it
// identically. Series colors are always var(--color-<dataKey>) — resolved
// by the ChartStyle <style> the <chart> container emits, never in JS.
//
// SSR-first: the whole chart body is server-rendered; the only client
// state is the hovered band index for the tooltip/cursor. Everything the
// client needs (cursor paths, tooltip rows, positions) is precomputed into
// plain serializable arrays — the d3 ctx (functions) never crosses into
// reactive scope.
import { configFor, seriesColor, type ChartConfig } from "./config.ts";
import {
  cartesianCtx,
  linePath,
  thinTicksByGap,
  type CartesianCtx,
  type CurveType,
  type Margin,
  type Row,
} from "./math.ts";
import { cn } from "../../../lib/utils.ts";
import ChartGrid from "./grid.marko";
import ChartXAxis from "./x-axis.marko";
import ChartYAxis from "./y-axis.marko";
import ChartTooltip from "./tooltip.marko";
import ChartLegend from "./legend.marko";

export interface LabelSpec {
  dataKey?: string;
  color?: string;
  formatter?: (value: string) => string;
}

export interface LineSeriesAttrs {
  dataKey: string;
  /** Curve type (default "natural" — the shadcn line-default demo). */
  type?: CurveType;
  strokeWidth?: number;
  /** Render point markers (default false — shadcn demos hide dots). */
  dot?: boolean;
  /** Dot fill comes from each row's own `fill` field instead of the series color (chart-line-dots-colors). */
  dotColorByRow?: boolean;
  /** Replaces the default <circle> dot with custom content per point (chart-line-dots-custom). */
  dotContent?: Marko.Body<[{ x: number; y: number; row: Row }]>;
  /** LabelList-equivalent: value (or another field) rendered above each point. */
  labels?: LabelSpec[];
}

export interface Input {
  /** Same object passed to <chart> — Marko has no context, so it travels twice. */
  config: ChartConfig;
  data: Row[];
  xKey: string;
  width?: number;
  height?: number;
  margin?: Partial<Margin>;
  /** false ⇒ no tooltip (and no hover state at all). Default true. */
  tooltip?: boolean;
  /** false ⇒ no hover cursor line. Default true. */
  cursor?: boolean;
  indicator?: "line" | "dot" | "dashed";
  hideLabel?: boolean;
  /** Horizontal grid lines (recharts <CartesianGrid vertical={false}/>). Default true. */
  grid?: boolean;
  /** Default false — matches the shadcn demos. */
  yAxis?: boolean;
  legend?: boolean | "top" | "bottom";
  xTickFormatter?: (value: string) => string;
  /** Minimum pixel gap between kept x-axis ticks (recharts XAxis minTickGap) — thins dense date-series ticks. */
  xTickMinGap?: number;
  /** Applied to the tooltip's label row only (recharts ChartTooltipContent labelFormatter). */
  tooltipLabelFormatter?: (value: string) => string;
  class?: string;
  series?: Marko.AttrTag<LineSeriesAttrs>;
}

// recharts default margin is 5 on every side; the shadcn line demos add
// left/right 12 — that composite is our default, overridable via margin=.
static const DEFAULT_MARGIN = { top: 5, right: 12, bottom: 5, left: 12 };
static const DEFAULT_WIDTH = 628;
static const DEFAULT_HEIGHT = 353;
static const X_AXIS_HEIGHT = 30;

export interface PointerGeo {
  width: number;
  plotX: number;
  plotWidth: number;
  count: number;
}

// Point-scale x positions, like recharts uses for line/area charts: the
// first point sits at the plot's left edge, the last at its right edge
// (the default left/right margin of 12 gives the curve breathing room).
// Same helper as area.marko — kept local because client hover handlers can
// only reference plain serializable data, not the d3 scales in ctx.
static function pointPositions(ctx: CartesianCtx, count: number): number[] {
  if (count <= 1) return [ctx.plot.x + ctx.plot.width / 2];
  const step = ctx.plot.width / (count - 1);
  return Array.from({ length: count }, (item, index) => ctx.plot.x + index * step);
}

// Pointer → nearest point index, on plain numbers only (point scale —
// nearest point wins, like recharts). Identical to area.marko's helper.
static function pointerIndex(
  offsetX: number,
  clientWidth: number,
  geo: PointerGeo,
): number {
  if (clientWidth <= 0 || geo.count === 0) return -1;
  const scaledX = offsetX * (geo.width / clientWidth);
  if (scaledX < geo.plotX || scaledX > geo.plotX + geo.plotWidth) return -1;
  if (geo.count === 1) return 0;
  const step = geo.plotWidth / (geo.count - 1);
  const index = Math.round((scaledX - geo.plotX) / step);
  return Math.max(0, Math.min(geo.count - 1, index));
}

static function labelOf(config: ChartConfig, key: string): string {
  const entry = configFor(config, key);
  return entry && entry.label ? entry.label : key;
}

export interface SeriesRender {
  dataKey: string;
  color: string;
  strokeWidth: number;
  dot: boolean;
  dotColorByRow: boolean;
  dotContent?: Marko.Body<[{ x: number; y: number; row: Row }]>;
  labels?: LabelSpec[];
  path: string;
  points: { x: number; y: number; row: Row }[];
}

static function dotColor(row: Row, fallback: string): string {
  const fill = row["fill"];
  if (typeof fill === "string" && fill !== "") return fill;
  return fallback;
}

static function buildSeries(
  seriesList: LineSeriesAttrs[],
  data: Row[],
  centers: number[],
  yScale: (value: number) => number,
): SeriesRender[] {
  return seriesList.map((series) => {
    const yFor = (row: Row) => yScale(Number(row[series.dataKey] ?? 0));
    return {
      dataKey: series.dataKey,
      color: seriesColor(series.dataKey),
      strokeWidth: series.strokeWidth ?? 2,
      dot: series.dot === true,
      dotColorByRow: series.dotColorByRow === true,
      dotContent: series.dotContent,
      labels: series.labels,
      path: linePath(
        data,
        (row, index) => centers[index] ?? 0,
        yFor,
        series.type ?? "natural",
      ),
      points: data.map((row, index) => ({
        x: centers[index] ?? 0,
        y: yFor(row),
        row,
      })),
    };
  });
}

export interface TooltipRowData {
  key: string;
  label: string;
  value: number | string;
  color: string;
}

static function buildTooltipRows(
  seriesList: LineSeriesAttrs[],
  data: Row[],
  config: ChartConfig,
): TooltipRowData[][] {
  return data.map((row) =>
    seriesList.map((series) => ({
      key: series.dataKey,
      label: labelOf(config, series.dataKey),
      value: Number(row[series.dataKey] ?? 0),
      color: series.dotColorByRow ? dotColor(row, seriesColor(series.dataKey)) : seriesColor(series.dataKey),
    })),
  );
}

<const/{ config, data, xKey, class: className }=input/>
<const/seriesList=[...(input.series ?? [])]/>
<const/seriesKeys=seriesList.map((series) => series.dataKey)/>
<const/width=(input.width ?? DEFAULT_WIDTH)/>
<const/height=(input.height ?? DEFAULT_HEIGHT)/>
<const/margin={ ...DEFAULT_MARGIN, ...input.margin }/>
<const/showTooltip=(input.tooltip !== false)/>
<const/showCursor=(input.cursor !== false)/>
<const/showGrid=(input.grid !== false)/>
<const/showLegend=(input.legend === true || input.legend === "top" || input.legend === "bottom")/>
<const/legendPosition=(input.legend === "top" ? "top" : "bottom")/>
<const/indicator=input.indicator/>
<const/hideLabel=input.hideLabel/>
<const/formatter=input.xTickFormatter/>

<const/ctx=cartesianCtx({
  data,
  xKey,
  seriesKeys,
  width,
  height,
  margin,
  xAxisHeight: X_AXIS_HEIGHT,
  paddingInner: 0,
  paddingOuter: 0,
})/>
<const/centers=pointPositions(ctx, data.length)/>
<const/renderSeries=buildSeries(seriesList, data, centers, ctx.y)/>
<const/allTicks=data.map((row, index) => ({ value: (formatter ? formatter(String(row[xKey])) : String(row[xKey])), x: centers[index] ?? 0 }))/>
<const/ticks=(input.xTickMinGap ? thinTicksByGap(allTicks, input.xTickMinGap) : allTicks)/>
<const/legendItems=seriesList.map((series) => ({ key: series.dataKey, label: labelOf(config, series.dataKey), color: seriesColor(series.dataKey) }))/>

// Plain serializable arrays for the client-reactive region (see header note).
<const/cursorPaths=centers.map((x) => (`M ${x},${ctx.plot.y} L ${x},${ctx.plot.y + ctx.plot.height}`))/>
<const/leftPcts=centers.map((x) => Math.min(88, Math.max(12, (x / width) * 100)))/>
<const/tooltipRows=buildTooltipRows(seriesList, data, config)/>
<const/xLabels=data.map((row) => (input.tooltipLabelFormatter ? input.tooltipLabelFormatter(String(row[xKey])) : String(row[xKey])))/>
<const/geo={ width, plotX: ctx.plot.x, plotWidth: ctx.plot.width, count: data.length }/>

<let/activeIndex=(-1)/>
// Bind the active row rather than indexing in the template: `activeIndex >= 0`
// alone does not prove the index is still within `tooltipRows` (a stale index
// survives a `data` change), so guard on the looked-up value instead.
<const/activeRows=(activeIndex >= 0 ? tooltipRows[activeIndex] : undefined)/>

<div
  class=cn("recharts-wrapper", className)
  style={ position: "relative", width: "100%", height: "100%" }
  onPointerMove(event: PointerEvent, el: HTMLDivElement) {
    if (showTooltip) {
      // offsetX is relative to the event TARGET (an inner svg node when
      // hovering the chart), so derive the wrapper-relative x from clientX.
      const rect = el.getBoundingClientRect();
      activeIndex = pointerIndex(event.clientX - rect.left, rect.width, geo);
    }
  }
  onPointerLeave() {
    activeIndex = -1;
  }
>
  <if=(showLegend && legendPosition === "top")>
    <ChartLegend items=legendItems verticalAlign="top"/>
  </if>
  <svg
    class="recharts-surface"
    width="100%"
    height="100%"
    viewBox=`0 0 ${width} ${height}`
  >
    <if=showGrid>
      <ChartGrid ctx=ctx/>
    </if>
    <if=(showTooltip && showCursor && activeIndex >= 0)>
      <g class="recharts-layer">
        <path
          class="recharts-curve recharts-tooltip-cursor"
          stroke="#ccc"
          pointer-events="none"
          fill="none"
          d=cursorPaths[activeIndex]
        />
      </g>
    </if>
    <ChartXAxis ctx=ctx ticks=ticks/>
    <if=input.yAxis>
      <ChartYAxis ctx=ctx/>
    </if>
    <for|series| of=renderSeries>
      <g class="recharts-layer recharts-line">
        <path
          class="recharts-curve recharts-line-curve"
          stroke=series.color
          fill="none"
          stroke-width=series.strokeWidth
          d=series.path
        />
        <if=series.dotContent>
          <g class="recharts-layer recharts-line-dots">
            <for|point| of=series.points>
              <${series.dotContent}({ x: point.x, y: point.y, row: point.row })/>
            </for>
          </g>
        </if>
        <else-if=series.dot>
          <g class="recharts-layer recharts-line-dots">
            <for|point| of=series.points>
              <circle
                class="recharts-dot recharts-line-dot"
                r="3"
                stroke="#fff"
                stroke-width="1"
                fill=(series.dotColorByRow ? dotColor(point.row, series.color) : series.color)
                cx=point.x
                cy=point.y
              />
            </for>
          </g>
        </else-if>
        <if=series.labels>
          <g class="recharts-layer recharts-label-list">
            <for|point| of=series.points>
              <for|spec| of=series.labels>
                <const/labelValue=(spec.dataKey ? String(point.row[spec.dataKey] ?? "") : String(point.row[series.dataKey] ?? ""))/>
                <const/labelText=(spec.formatter ? spec.formatter(labelValue) : labelValue)/>
                <text
                  x=point.x
                  y=(point.y - 12)
                  text-anchor="middle"
                  fill=(spec.color ?? "var(--foreground)")
                  font-size="12"
                  class="recharts-text"
                >${labelText}</text>
              </for>
            </for>
          </g>
        </if>
      </g>
    </for>
  </svg>
  <if=(showLegend && legendPosition === "bottom")>
    <ChartLegend items=legendItems verticalAlign="bottom"/>
  </if>
  <if=(showTooltip && activeRows)>
    <div
      style={
        position: "absolute",
        left: `${leftPcts[activeIndex]}%`,
        top: "12px",
        transform: "translateX(-50%)",
        "pointer-events": "none",
      }
    >
      <ChartTooltip
        rows=activeRows
        label=xLabels[activeIndex]
        indicator=indicator
        hideLabel=hideLabel
      />
    </div>
  </if>
</div>

// d3 wrappers + geometry for the chart components. Pure math — no DOM,
// no d3-selection; Marko templates emit all SVG. Everything type-heavy
// (generics, method chains) lives here because .marko files can't hold
// inline generics or indented method-chain continuations.

import { scaleBand, scaleLinear, type ScaleBand, type ScaleLinear } from "d3-scale";
import {
  arc,
  area,
  line,
  pie,
  stack,
  stackOffsetExpand,
  curveLinear,
  curveMonotoneX,
  curveNatural,
  curveStep,
  type PieArcDatum,
  type Series,
} from "d3-shape";
import { max, min } from "d3-array";

export type Row = Record<string, unknown>;

export interface Margin {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface PlotArea {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface CartesianCtx {
  /** viewBox size */
  width: number;
  height: number;
  margin: Margin;
  plot: PlotArea;
  xBand: ScaleBand<string>;
  y: ScaleLinear<number, number>;
  // Carried along so partials/chart tags don't need to re-thread them.
  data: Row[];
  xKey: string;
  seriesKeys: string[];
}

const ZERO_MARGIN: Margin = { top: 0, right: 0, bottom: 0, left: 0 };

function numberAt(row: Row, key: string): number {
  const value = row[key];
  return typeof value === "number" ? value : Number(value ?? 0);
}

export interface CartesianCtxOptions {
  data: Row[];
  xKey: string;
  seriesKeys: string[];
  width: number;
  height: number;
  margin?: Partial<Margin>;
  /** Vertical space reserved for the x axis (recharts default: 30). */
  xAxisHeight: number;
  stacked?: boolean;
  yDomain?: [number, number];
  /**
   * Band paddings. Defaults match recharts' bar defaults
   * (barCategoryGap "10%" of the band on each side): inner 0.2, outer 0.1.
   * Line/area charts pass 0/0 so points sit at band centers spanning the plot.
   */
  paddingInner?: number;
  paddingOuter?: number;
  /** "expand" ⇒ y domain is fixed to [0, 1] (100% stacked), like recharts' stackOffset="expand". */
  stackOffset?: "expand";
}

export function cartesianCtx(opts: CartesianCtxOptions): CartesianCtx {
  const margin: Margin = { ...ZERO_MARGIN, ...opts.margin };
  const plot: PlotArea = {
    x: margin.left,
    y: margin.top,
    width: opts.width - margin.left - margin.right,
    height: opts.height - margin.top - margin.bottom - opts.xAxisHeight,
  };

  const xBand = scaleBand<string>()
    .domain(opts.data.map((row) => String(row[opts.xKey])))
    .range([plot.x, plot.x + plot.width])
    .paddingInner(opts.paddingInner ?? 0.2)
    .paddingOuter(opts.paddingOuter ?? 0.1);

  let domain = opts.yDomain;
  if (!domain && opts.stackOffset === "expand") {
    domain = [0, 1];
  }
  if (!domain) {
    let dataMax: number;
    let dataMin: number;
    if (opts.stacked) {
      const sums = opts.data.map((row) =>
        opts.seriesKeys.reduce((total, key) => total + numberAt(row, key), 0),
      );
      dataMax = max(sums) ?? 0;
      dataMin = min(sums.map((sum) => Math.min(sum, 0))) ?? 0;
    } else {
      const values = opts.data.flatMap((row) =>
        opts.seriesKeys.map((key) => numberAt(row, key)),
      );
      dataMax = max(values) ?? 0;
      dataMin = min(values) ?? 0;
    }
    // recharts default: [min(0, dataMin), niceMax]
    domain = [Math.min(0, dataMin), dataMax];
  }

  const y = scaleLinear()
    .domain(domain)
    .range([plot.y + plot.height, plot.y])
    .nice();

  return {
    width: opts.width,
    height: opts.height,
    margin,
    plot,
    xBand,
    y,
    data: opts.data,
    xKey: opts.xKey,
    seriesKeys: opts.seriesKeys,
  };
}

export const CURVES = {
  natural: curveNatural,
  linear: curveLinear,
  monotone: curveMonotoneX,
  step: curveStep,
} as const;

export type CurveType = keyof typeof CURVES;

export function linePath(
  data: Row[],
  xAccessor: (row: Row, index: number) => number,
  yAccessor: (row: Row, index: number) => number,
  curve: CurveType = "natural",
): string {
  const generator = line<Row>()
    .x(xAccessor)
    .y(yAccessor)
    .curve(CURVES[curve]);
  return generator(data) ?? "";
}

export function areaPaths(
  data: Row[],
  xAccessor: (row: Row, index: number) => number,
  y0Accessor: (row: Row, index: number) => number,
  y1Accessor: (row: Row, index: number) => number,
  curve: CurveType = "natural",
): { area: string; line: string } {
  const areaGenerator = area<Row>()
    .x(xAccessor)
    .y0(y0Accessor)
    .y1(y1Accessor)
    .curve(CURVES[curve]);
  const lineGenerator = line<Row>()
    .x(xAccessor)
    .y(y1Accessor)
    .curve(CURVES[curve]);
  return { area: areaGenerator(data) ?? "", line: lineGenerator(data) ?? "" };
}

/**
 * d3 stack over `keys` — for stacked bars/areas. Output[s][i] = [y0, y1].
 * `offset: "expand"` normalizes each row's stack to [0, 1] (recharts'
 * `stackOffset="expand"`, used by chart-area-stacked-expand) — every layer's
 * [y0, y1] becomes a fraction of that row's total.
 */
export function stackSeries(
  data: Row[],
  keys: string[],
  options?: { offset?: "expand" },
): Series<Row, string>[] {
  const generator = stack<Row, string>()
    .keys(keys)
    .value((row, key) => numberAt(row, key));
  if (options?.offset === "expand") {
    generator.offset(stackOffsetExpand);
  }
  return generator(data);
}

export type CornerRadius = number | [number, number, number, number];

/**
 * Rounded-rect path with recharts Rectangle parity: a number radius rounds
 * all 4 corners; a [topLeft, topRight, bottomRight, bottomLeft] tuple rounds
 * individually (recharts accepts this for stacked bars). Radii are clamped
 * to half the width/height.
 */
export function roundedRectPath(
  x: number,
  y: number,
  width: number,
  height: number,
  radius: CornerRadius = 0,
): string {
  const limit = Math.min(Math.abs(width) / 2, Math.abs(height) / 2);
  const clamp = (value: number) => Math.max(0, Math.min(limit, value));
  const corners: [number, number, number, number] =
    typeof radius === "number" ? [radius, radius, radius, radius] : radius;
  const topLeft = clamp(corners[0]);
  const topRight = clamp(corners[1]);
  const bottomRight = clamp(corners[2]);
  const bottomLeft = clamp(corners[3]);

  return (
    `M ${x},${y + topLeft}` +
    (topLeft > 0 ? ` A ${topLeft},${topLeft},0,0,1,${x + topLeft},${y}` : "") +
    ` L ${x + width - topRight},${y}` +
    (topRight > 0
      ? ` A ${topRight},${topRight},0,0,1,${x + width},${y + topRight}`
      : "") +
    ` L ${x + width},${y + height - bottomRight}` +
    (bottomRight > 0
      ? ` A ${bottomRight},${bottomRight},0,0,1,${x + width - bottomRight},${y + height}`
      : "") +
    ` L ${x + bottomLeft},${y + height}` +
    (bottomLeft > 0
      ? ` A ${bottomLeft},${bottomLeft},0,0,1,${x},${y + height - bottomLeft}`
      : "") +
    " Z"
  );
}

export interface PieArc {
  /** The `d` attribute for the sector's <path>. */
  path: string;
  row: Row;
  index: number;
  value: number;
  startAngle: number;
  endAngle: number;
  /** [x, y] centroid relative to the pie center — for labels. */
  centroid: [number, number];
}

export interface PieArcsOptions {
  innerRadius: number;
  outerRadius: number;
  /** Degrees, like recharts' paddingAngle. */
  paddingAngle?: number;
}

/**
 * d3 pie() with sort(null) — keeps input order like recharts. d3's default
 * start angle (0 at 12 o'clock, clockwise) matches how the shadcn pie demos
 * render.
 */
export function pieArcs(
  data: Row[],
  valueKey: string,
  opts: PieArcsOptions,
): PieArc[] {
  const pieGenerator = pie<Row>()
    .sort(null)
    .value((row) => numberAt(row, valueKey))
    .padAngle(((opts.paddingAngle ?? 0) * Math.PI) / 180);
  const arcGenerator = arc<PieArcDatum<Row>>()
    .innerRadius(opts.innerRadius)
    .outerRadius(opts.outerRadius);

  return pieGenerator(data).map((datum) => ({
    path: arcGenerator(datum) ?? "",
    row: datum.data,
    index: datum.index,
    value: datum.value,
    startAngle: datum.startAngle,
    endAngle: datum.endAngle,
    centroid: arcGenerator.centroid(datum),
  }));
}

export interface XTick {
  value: string;
  x: number;
}

/**
 * Thins a list of x-position ticks so consecutive kept ticks are at least
 * `minGap` pixels apart — recharts' XAxis `minTickGap` (used by every
 * shadcn chart with a dense date-series x axis, e.g. chart-area-interactive's
 * 90 daily points). Always keeps the first tick; each subsequent tick is
 * kept only if it's `minGap` past the last KEPT tick's x position.
 */
export function thinTicksByGap<T extends { x: number }>(ticks: T[], minGap: number): T[] {
  const first = ticks[0];
  if (minGap <= 0 || first === undefined) return ticks;
  const kept: T[] = [first];
  let lastX = first.x;
  for (let i = 1; i < ticks.length; i++) {
    const tick = ticks[i];
    if (tick === undefined) continue;
    if (tick.x - lastX >= minGap) {
      kept.push(tick);
      lastX = tick.x;
    }
  }
  return kept;
}

export interface YTick {
  value: number;
  y: number;
}

/** One tick per band, positioned at the band center. */
export function xTicks(ctx: CartesianCtx): XTick[] {
  const halfBand = ctx.xBand.bandwidth() / 2;
  return ctx.xBand.domain().map((value) => ({
    value,
    x: (ctx.xBand(value) ?? 0) + halfBand,
  }));
}

/** Nice y ticks (d3 `ticks`) with their pixel positions. */
export function yTicks(ctx: CartesianCtx, count = 5): YTick[] {
  return ctx.y.ticks(count).map((value) => ({ value, y: ctx.y(value) }));
}

/** Center x of a band by data index — line/area point positions. */
export function bandCenter(ctx: CartesianCtx, index: number): number {
  const value = ctx.xBand.domain()[index];
  if (value === undefined) return ctx.plot.x;
  return (ctx.xBand(value) ?? 0) + ctx.xBand.bandwidth() / 2;
}

/**
 * Pointer offsetX (CSS pixels) -> data index. Scales by viewBox/client width
 * (the SVG is scaled by CSS), then locates the band step under the pointer.
 * Clamped to [0, n-1]; returns -1 outside the plot area.
 */
export function bandIndexFromPointer(
  offsetX: number,
  clientWidth: number,
  ctx: CartesianCtx,
): number {
  const domain = ctx.xBand.domain();
  const firstValue = domain[0];
  if (firstValue === undefined || clientWidth <= 0) return -1;
  const scaledX = offsetX * (ctx.width / clientWidth);
  if (scaledX < ctx.plot.x || scaledX > ctx.plot.x + ctx.plot.width) return -1;
  const step = ctx.xBand.step();
  const first = ctx.xBand(firstValue) ?? 0;
  const start = first - ctx.xBand.paddingInner() * step * 0.5;
  const index = Math.floor((scaledX - start) / step);
  return Math.max(0, Math.min(domain.length - 1, index));
}

/**
 * The `d` for the tooltip cursor rect covering the whole band step at
 * `index`, spanning the plot height (recharts bar-chart cursor).
 */
export function bandCursorPath(ctx: CartesianCtx, index: number): string {
  const domain = ctx.xBand.domain();
  const value = domain[index];
  if (value === undefined) return "";
  const step = ctx.xBand.step();
  const x = (ctx.xBand(value) ?? 0) - ctx.xBand.paddingInner() * step * 0.5;
  return roundedRectPath(x, ctx.plot.y, step, ctx.plot.height, 0);
}

// ---------------------------------------------------------------------------
// Horizontal layout (recharts' <BarChart layout="vertical">, which despite
// the name draws horizontal bars: a category scale banded on the Y axis, a
// linear value scale on the X axis, bars extending rightward from x=0).
// A separate context type rather than an `orientation` flag on CartesianCtx:
// the two contexts have genuinely different roles for x/y (band-on-y vs
// band-on-x), so reusing one shape would need every consumer to branch on
// orientation. Keeping them distinct means bar.marko's vertical path is
// untouched and the horizontal path is additive.
export interface HorizontalCtx {
  width: number;
  height: number;
  margin: Margin;
  plot: PlotArea;
  /** Category scale, banded on the Y axis. */
  yBand: ScaleBand<string>;
  /** Value scale, linear on the X axis — bars run from x(0) to x(value). */
  x: ScaleLinear<number, number>;
  data: Row[];
  yKey: string;
  seriesKeys: string[];
}

export interface HorizontalCtxOptions {
  data: Row[];
  /** Category field, e.g. "browser" — becomes the Y-axis band. */
  yKey: string;
  seriesKeys: string[];
  width: number;
  height: number;
  margin?: Partial<Margin>;
  /** Horizontal space reserved for the (hidden or visible) Y axis labels. */
  yAxisWidth?: number;
  stacked?: boolean;
  xDomain?: [number, number];
  paddingInner?: number;
  paddingOuter?: number;
}

export function horizontalCtx(opts: HorizontalCtxOptions): HorizontalCtx {
  const margin: Margin = { ...ZERO_MARGIN, ...opts.margin };
  const yAxisWidth = opts.yAxisWidth ?? 0;
  const plot: PlotArea = {
    x: margin.left + yAxisWidth,
    y: margin.top,
    width: opts.width - margin.left - margin.right - yAxisWidth,
    height: opts.height - margin.top - margin.bottom,
  };

  const yBand = scaleBand<string>()
    .domain(opts.data.map((row) => String(row[opts.yKey])))
    .range([plot.y, plot.y + plot.height])
    .paddingInner(opts.paddingInner ?? 0.2)
    .paddingOuter(opts.paddingOuter ?? 0.1);

  let domain = opts.xDomain;
  if (!domain) {
    let dataMax: number;
    let dataMin: number;
    if (opts.stacked) {
      const sums = opts.data.map((row) =>
        opts.seriesKeys.reduce((total, key) => total + numberAt(row, key), 0),
      );
      dataMax = max(sums) ?? 0;
      dataMin = min(sums.map((sum) => Math.min(sum, 0))) ?? 0;
    } else {
      const values = opts.data.flatMap((row) =>
        opts.seriesKeys.map((key) => numberAt(row, key)),
      );
      dataMax = max(values) ?? 0;
      dataMin = min(values) ?? 0;
    }
    domain = [Math.min(0, dataMin), dataMax];
  }

  const x = scaleLinear()
    .domain(domain)
    .range([plot.x, plot.x + plot.width])
    .nice();

  return {
    width: opts.width,
    height: opts.height,
    margin,
    plot,
    yBand,
    x,
    data: opts.data,
    yKey: opts.yKey,
    seriesKeys: opts.seriesKeys,
  };
}

export interface HTick {
  value: string;
  y: number;
}

/** One tick per band, positioned at the band center — for the Y (category) axis. */
export function hBandTicks(ctx: HorizontalCtx): HTick[] {
  const halfBand = ctx.yBand.bandwidth() / 2;
  return ctx.yBand.domain().map((value) => ({
    value,
    y: (ctx.yBand(value) ?? 0) + halfBand,
  }));
}

/** Center y of a band by data index. */
export function hBandCenter(ctx: HorizontalCtx, index: number): number {
  const value = ctx.yBand.domain()[index];
  if (value === undefined) return ctx.plot.y;
  return (ctx.yBand(value) ?? 0) + ctx.yBand.bandwidth() / 2;
}

/**
 * Pointer offsetY (CSS pixels) -> data index, for horizontal-layout hover.
 * Mirrors bandIndexFromPointer but on the Y axis.
 */
export function hBandIndexFromPointer(
  offsetY: number,
  clientHeight: number,
  ctx: HorizontalCtx,
): number {
  const domain = ctx.yBand.domain();
  const firstValue = domain[0];
  if (firstValue === undefined || clientHeight <= 0) return -1;
  const scaledY = offsetY * (ctx.height / clientHeight);
  if (scaledY < ctx.plot.y || scaledY > ctx.plot.y + ctx.plot.height) return -1;
  const step = ctx.yBand.step();
  const first = ctx.yBand(firstValue) ?? 0;
  const start = first - ctx.yBand.paddingInner() * step * 0.5;
  const index = Math.floor((scaledY - start) / step);
  return Math.max(0, Math.min(domain.length - 1, index));
}

/** Tooltip cursor rect for the whole band at `index`, spanning the plot width. */
export function hBandCursorPath(ctx: HorizontalCtx, index: number): string {
  const domain = ctx.yBand.domain();
  const value = domain[index];
  if (value === undefined) return "";
  const step = ctx.yBand.step();
  const y = (ctx.yBand(value) ?? 0) - ctx.yBand.paddingInner() * step * 0.5;
  return roundedRectPath(ctx.plot.x, y, ctx.plot.width, step, 0);
}

// <chart-pie-chart> — pie/donut chart with recharts-parity SVG markup.
// d3 (via math.ts pieArcs) is geometry only; every visible class and
// attribute matches what recharts renders inside shadcn's ChartContainer:
// sectors are `class="recharts-sector" stroke="#fff"` (literal — the
// container CSS turns it into stroke-transparent), layers are
// `recharts-layer`, the svg is `recharts-surface`. Slice colors come from
// each row's `fill` (shadcn pie demos put `fill: "var(--color-chrome)"` in
// the data) or fall back to `var(--color-<row[nameKey]>)` — never resolved
// in JS, so a shadcn theme's --chart-1..5 variables restyle everything.
import { pieArcs, type PieArc, type Row } from "./math.ts";
import { configFor, type ChartConfig } from "./config.ts";
import { cn } from "../../../lib/utils.ts";
import ChartTooltip from "./tooltip.marko";
import ChartLegend from "./legend.marko";

/** A second (or further) concentric ring — e.g. chart-pie-stacked's two donuts. */
export interface PieRing {
  data: Row[];
  dataKey: string;
  nameKey?: string;
  innerRadius?: number;
  outerRadius?: number;
  paddingAngle?: number;
}

export interface Input {
  /** Same object passed to <Chart> — Marko has no context, so it's passed twice. */
  config: ChartConfig;
  data: Row[];
  /** Value field, e.g. "visitors". */
  dataKey: string;
  /** Category field, e.g. "browser". */
  nameKey: string;
  /** viewBox size — the container's CSS aspect scales the drawing. */
  width?: number;
  height?: number;
  /** Donut when > 0 (recharts default 0). */
  innerRadius?: number;
  /** Defaults to 80% of the max radius, like recharts. */
  outerRadius?: number;
  /** Degrees between sectors, like recharts' paddingAngle. */
  paddingAngle?: number;
  /** Sector border width (recharts Pie strokeWidth, default 1). 0 removes the white separator. */
  strokeWidth?: number;
  tooltip?: boolean;
  indicator?: "line" | "dot" | "dashed";
  legend?: boolean | "top" | "bottom";
  /** Rendered inside the svg, receives the pie center — for donut text. */
  centerLabel?: Marko.Body<[{ cx: number; cy: number }]>;
  /** Plain numeric-value label with a leader line, positioned outside each slice (recharts' bare `label` prop). */
  outsideLabel?: boolean;
  /** Custom label rendered at each slice's centroid — e.g. value-in-foreground-color or category-name-in-background-color. */
  sliceLabel?: Marko.Body<[{ x: number; y: number; row: Row; value: number; index: number }]>;
  /** Highlights one sector at outerRadius + activeOuterRadiusDelta (default 10) — mirrors chart-pie-donut-active / chart-pie-interactive. */
  activeIndex?: number;
  activeOuterRadiusDelta?: number;
  /** Additional concentric rings — e.g. chart-pie-stacked's inner/outer donut pair. `data`'s own ring uses `dataKey`/`nameKey`/`innerRadius`/`outerRadius` above as ring 0. */
  rings?: PieRing[];
  class?: string;
}

static function sliceColor(row: Row, nameKey: string): string {
  const fill = row["fill"];
  if (typeof fill === "string" && fill !== "") return fill;
  return `var(--color-${String(row[nameKey])})`;
}

static function sliceLabelText(
  config: ChartConfig,
  row: Row,
  nameKey: string,
): string {
  const name = String(row[nameKey]);
  return configFor(config, name)?.label ?? name;
}

static function legendItemsFor(
  config: ChartConfig,
  data: Row[],
  nameKey: string,
): { key: string; label: string; color: string }[] {
  return data.map((row) => ({
    key: String(row[nameKey]),
    label: sliceLabelText(config, row, nameKey),
    color: sliceColor(row, nameKey),
  }));
}

static function tooltipRowsFor(
  config: ChartConfig,
  row: Row,
  nameKey: string,
  value: number,
): { key: string; label: string; value: number; color: string }[] {
  return [
    {
      key: String(row[nameKey]),
      label: sliceLabelText(config, row, nameKey),
      value,
      color: sliceColor(row, nameKey),
    },
  ];
}

// Outside-label leader-line geometry, mirroring recharts' default Pie label
// line: from the arc's midpoint outward a short distance, then horizontal.
static function outsideLabelGeometry(
  arc: PieArc,
  cx: number,
  cy: number,
  outer: number,
): { line: string; x: number; y: number; anchor: "start" | "end" } {
  const midAngle = (arc.startAngle + arc.endAngle) / 2;
  // d3 pie angles: 0 at 12 o'clock, clockwise. Convert to standard trig.
  const sin = Math.sin(midAngle);
  const cos = -Math.cos(midAngle);
  const startR = outer;
  const bendR = outer + 12;
  const sx = cx + startR * sin;
  const sy = cy + startR * cos;
  const bx = cx + bendR * sin;
  const by = cy + bendR * cos;
  const anchor: "start" | "end" = sin >= 0 ? "start" : "end";
  const ex = bx + (anchor === "start" ? 16 : -16);
  return { line: `M ${sx},${sy} L ${bx},${by} L ${ex},${by}`, x: ex, y: by, anchor };
}

<const/{
  config,
  data,
  dataKey,
  nameKey,
  width = 250,
  height = 250,
  innerRadius = 0,
  outerRadius,
  paddingAngle,
  strokeWidth,
  tooltip: showTooltip = true,
  indicator = "dot",
  legend,
  centerLabel,
  outsideLabel,
  sliceLabel,
  activeIndex: staticActiveIndex,
  activeOuterRadiusDelta = 10,
  rings,
  class: className,
}=input/>
<const/cx=(width / 2)/>
<const/cy=(height / 2)/>
<const/outer=(outerRadius ?? Math.min(width, height) * 0.4)/>
<const/arcs=pieArcs(data, dataKey, { innerRadius, outerRadius: outer, paddingAngle })/>
<const/ringArcs=(rings ?? []).map((ring) => ({
  ring,
  arcs: pieArcs(ring.data, ring.dataKey, {
    innerRadius: ring.innerRadius ?? 0,
    outerRadius: ring.outerRadius ?? outer,
    paddingAngle: ring.paddingAngle,
  }),
}))/>
<let/activeIndex=(-1)/>
<const/effectiveActive=(staticActiveIndex != null ? staticActiveIndex : activeIndex)/>
<const/activeArc=(showTooltip && activeIndex >= 0 ? arcs[activeIndex] : undefined)/>

<div
  class=cn("recharts-wrapper flex h-full w-full flex-col", className)
  style={ position: "relative" }
  onPointerLeave() { activeIndex = -1; }
>
  <if=(legend === "top")>
    <ChartLegend
      items=legendItemsFor(config, data, nameKey)
      verticalAlign="top"
    />
  </if>
  <svg
    class="recharts-surface"
    width="100%"
    height="100%"
    viewBox=`0 0 ${width} ${height}`
  >
    <g class="recharts-layer recharts-pie" transform=`translate(${cx}, ${cy})`>
      <for|arcDatum| of=arcs>
        <const/isActive=(effectiveActive === arcDatum.index)/>
        <g class="recharts-layer recharts-pie-sector">
          <path
            class="recharts-sector"
            stroke="#fff"
            stroke-width=strokeWidth
            fill=sliceColor(arcDatum.row, nameKey)
            d=(isActive
              ? pieArcs(data, dataKey, { innerRadius, outerRadius: outer + activeOuterRadiusDelta, paddingAngle })[arcDatum.index]?.path ?? arcDatum.path
              : arcDatum.path)
            onPointerEnter() { activeIndex = arcDatum.index; }
          />
        </g>
      </for>
    </g>
    <for|entry| of=ringArcs>
      <const/ringCx=cx/>
      <const/ringCy=cy/>
      <g class="recharts-layer recharts-pie" transform=`translate(${ringCx}, ${ringCy})`>
        <for|arcDatum| of=entry.arcs>
          <g class="recharts-layer recharts-pie-sector">
            <path
              class="recharts-sector"
              stroke="#fff"
              fill=sliceColor(arcDatum.row, entry.ring.nameKey ?? nameKey)
              d=arcDatum.path
            />
          </g>
        </for>
      </g>
    </for>
    <if=outsideLabel>
      <g class="recharts-layer">
        <for|arcDatum| of=arcs>
          <const/geom=outsideLabelGeometry(arcDatum, cx, cy, outer)/>
          <path class="recharts-curve recharts-pie-label-line" stroke="#666" fill="none" d=geom.line/>
          <text
            class="recharts-text recharts-pie-label-text"
            x=geom.x
            y=geom.y
            text-anchor=geom.anchor
            dominant-baseline="central"
          >${arcDatum.value}</text>
        </for>
      </g>
    </if>
    <if=sliceLabel>
      <g class="recharts-layer recharts-label-list">
        <for|arcDatum| of=arcs>
          <${sliceLabel}({ x: cx + arcDatum.centroid[0], y: cy + arcDatum.centroid[1], row: arcDatum.row, value: arcDatum.value, index: arcDatum.index })/>
        </for>
      </g>
    </if>
    <if=centerLabel>
      <${centerLabel}({ cx, cy })/>
    </if>
  </svg>
  <if=(legend === true || legend === "bottom")>
    <ChartLegend
      items=legendItemsFor(config, data, nameKey)
      verticalAlign="bottom"
    />
  </if>
  <if=activeArc>
    <div
      style={
        position: "absolute",
        left: "50%",
        top: "12px",
        transform: "translateX(-50%)",
        "pointer-events": "none",
      }
    >
      <ChartTooltip
        rows=tooltipRowsFor(config, activeArc.row, nameKey, activeArc.value)
        indicator=indicator
        hideLabel
      />
    </div>
  </if>
</div>

// ChartTooltipContent — presentational Marko port of shadcn's
// <ChartTooltipContent>. Class strings are verbatim from chart.tsx,
// including the nestLabel behavior (single row + non-dot indicator moves
// the label inside the row). No state: the owning chart tag positions it
// and supplies resolved rows.
import { cn } from "../../../lib/utils.ts";

export interface TooltipRow {
  key: string;
  label: string;
  value: number | string;
  color: string;
  icon?: Marko.Renderable;
}

export interface Input extends Marko.Input<"div"> {
  rows: TooltipRow[];
  /** Resolved x label — already run through the chart config by the caller. */
  label?: string;
  indicator?: "line" | "dot" | "dashed";
  hideLabel?: boolean;
  hideIndicator?: boolean;
}

static function formatValue(value: number | string): string {
  return typeof value === "number" ? value.toLocaleString() : String(value);
}

<const/{
  rows,
  label,
  indicator = "dot",
  hideLabel,
  hideIndicator,
  class: className,
  ...rest
}=input/>
<const/showLabel=(!hideLabel && label != null && label !== "")/>
<const/nestLabel=(rows.length === 1 && indicator !== "dot")/>

<div
  ...rest
  class=cn(
    "border-border/50 bg-background gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs shadow-xl grid min-w-32 items-start",
    className,
  )
>
  <if=(showLabel && !nestLabel)>
    <div class="font-medium">${label}</div>
  </if>
  <div class="grid gap-1.5">
    <for|row| of=rows>
      <div
        class=cn(
          "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
          indicator === "dot" && "items-center",
        )
      >
        <if=row.icon>
          <${row.icon}/>
        </if>
        <else-if=(!hideIndicator)>
          <div
            class=cn(
              "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
              indicator === "dot" && "h-2.5 w-2.5",
              indicator === "line" && "w-1",
              indicator === "dashed" &&
                "w-0 border-[1.5px] border-dashed bg-transparent",
              nestLabel && indicator === "dashed" && "my-0.5",
            )
            style=`--color-bg: ${row.color}; --color-border: ${row.color};`
          ></div>
        </else-if>
        <div
          class=cn(
            "flex flex-1 justify-between leading-none",
            nestLabel ? "items-end" : "items-center",
          )
        >
          <div class="grid gap-1.5">
            <if=(showLabel && nestLabel)>
              <div class="font-medium">${label}</div>
            </if>
            <span class="text-muted-foreground">${row.label}</span>
          </div>
          <if=(row.value != null)>
            <span class="font-mono font-medium text-foreground tabular-nums">
              ${formatValue(row.value)}
            </span>
          </if>
        </div>
      </div>
    </for>
  </div>
</div>

// XAxis ticks — recharts-parity SVG partial (internal; ctx threaded by the
// chart tags). Tick <text> carries literal fill="#666" — the container's
// [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground restyles it.
// No axis line / tick lines: shadcn demos always pass tickLine={false}
// axisLine={false}, so we simply never render them. Any tickFormatter is
// applied by the CALLER before passing `ticks`.
import { xTicks, type CartesianCtx, type XTick } from "./math.ts";

export interface Input {
  ctx: CartesianCtx;
  ticks?: XTick[];
  tickMargin?: number;
}

<const/{ ctx, tickMargin = 8 }=input/>
<const/ticks=(input.ticks ?? xTicks(ctx))/>
<const/tickY=(ctx.plot.y + ctx.plot.height + tickMargin)/>

<g class="recharts-cartesian-axis recharts-xAxis xAxis">
  <g class="recharts-cartesian-axis-ticks">
    <for|tick| of=ticks>
      <g class="recharts-layer recharts-cartesian-axis-tick">
        <text
          stroke="none"
          fill="#666"
          class="recharts-text recharts-cartesian-axis-tick-value"
          x=tick.x
          y=tickY
          text-anchor="middle"
        ><tspan x=tick.x dy="0.71em">${tick.value}</tspan></text>
      </g>
    </for>
  </g>
</g>

// YAxis ticks — recharts-parity SVG partial (internal; ctx threaded by the
// chart tags). Only rendered when a chart tag gets `yAxis` (default off,
// matching the shadcn demos). Literal fill="#666" — restyled by the
// container's fill-muted-foreground selector. No axis/tick lines.
import { yTicks, type CartesianCtx, type YTick } from "./math.ts";

export interface Input {
  ctx: CartesianCtx;
  ticks?: YTick[];
  tickMargin?: number;
  /** Approximate number of ticks (d3 `ticks()` count) — recharts' tickCount. Default 5. */
  tickCount?: number;
}

<const/{ ctx, tickMargin = 8 }=input/>
<const/ticks=(input.ticks ?? yTicks(ctx, input.tickCount))/>
<const/tickX=(ctx.plot.x - tickMargin)/>

<g class="recharts-cartesian-axis recharts-yAxis yAxis">
  <g class="recharts-cartesian-axis-ticks">
    <for|tick| of=ticks>
      <g class="recharts-layer recharts-cartesian-axis-tick">
        <text
          stroke="none"
          fill="#666"
          class="recharts-text recharts-cartesian-axis-tick-value"
          x=tickX
          y=tick.y
          text-anchor="end"
        ><tspan x=tickX dy="0.355em">${tick.value}</tspan></text>
      </g>
    </for>
  </g>
</g>
